namespace ShipmentTracker.Client.Services;

public enum ShipmentStatus
{
    Pending,
    InTransit,
    OutForDelivery,
    Delivered,
    Delayed
}

public class ShipmentSummary
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public string CustomerName { get; set; } = string.Empty;
    public DateTimeOffset EstimatedDelivery { get; set; }
    public DateTimeOffset ShippedDate { get; set; }
}

namespace ShipmentTracker.Client.Services;

public interface IShipmentService
{
    Task<List<ShipmentSummary>> GetAllShipmentsAsync();
    Task<ShipmentSummary?> GetShipmentByTrackingNumberAsync(string trackingNumber);
    Task UpdateStatusAsync(int id, ShipmentStatus newStatus);
}

using System.Net.Http.Json;

namespace ShipmentTracker.Client.Services;

public class ClientShipmentService(HttpClient http) : IShipmentService
{
    public async Task<List<ShipmentSummary>> GetAllShipmentsAsync()
    {
        return await http.GetFromJsonAsync<List<ShipmentSummary>>("api/shipments") ?? [];
    }

    public async Task<ShipmentSummary?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var response = await http.GetAsync($"api/shipments/track/{trackingNumber}");
        if (!response.IsSuccessStatusCode)
            return null;
        return await response.Content.ReadFromJsonAsync<ShipmentSummary>();
    }

    public async Task UpdateStatusAsync(int id, ShipmentStatus newStatus)
    {
        await http.PutAsJsonAsync($"api/shipments/{id}/status", newStatus);
    }
}

