using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Services;

/// <summary>
/// Server-side implementation with in-memory seed data.
/// Replace with EF Core–backed implementation for production.
/// </summary>
public class ServerShipmentService : IShipmentService
{
    private static readonly List<ShipmentSummary> _shipments =
    [
        new() { Id = 1, TrackingNumber = "TRK-1001", Destination = "New York, USA", Status = ShipmentStatus.InTransit, CustomerName = "Alice Johnson", ShippedDate = DateTimeOffset.UtcNow.AddDays(-3), EstimatedDelivery = DateTimeOffset.UtcNow.AddDays(2) },
        new() { Id = 2, TrackingNumber = "TRK-1002", Destination = "London, UK", Status = ShipmentStatus.Pending, CustomerName = "Bob Smith", ShippedDate = DateTimeOffset.UtcNow.AddDays(-1), EstimatedDelivery = DateTimeOffset.UtcNow.AddDays(5) },
        new() { Id = 3, TrackingNumber = "TRK-1003", Destination = "Tokyo, Japan", Status = ShipmentStatus.OutForDelivery, CustomerName = "Yuki Tanaka", ShippedDate = DateTimeOffset.UtcNow.AddDays(-5), EstimatedDelivery = DateTimeOffset.UtcNow },
        new() { Id = 4, TrackingNumber = "TRK-1004", Destination = "Sydney, Australia", Status = ShipmentStatus.Delivered, CustomerName = "Chris Lee", ShippedDate = DateTimeOffset.UtcNow.AddDays(-7), EstimatedDelivery = DateTimeOffset.UtcNow.AddDays(-1) },
        new() { Id = 5, TrackingNumber = "TRK-1005", Destination = "Berlin, Germany", Status = ShipmentStatus.Delayed, CustomerName = "Hans Mueller", ShippedDate = DateTimeOffset.UtcNow.AddDays(-4), EstimatedDelivery = DateTimeOffset.UtcNow.AddDays(3) },
    ];

    public Task<List<ShipmentSummary>> GetAllShipmentsAsync()
        => Task.FromResult(_shipments.ToList());

    public Task<ShipmentSummary?> GetShipmentByTrackingNumberAsync(string trackingNumber)
        => Task.FromResult(_shipments.FirstOrDefault(s =>
            s.TrackingNumber.Equals(trackingNumber, StringComparison.OrdinalIgnoreCase)));

    public Task UpdateStatusAsync(int id, ShipmentStatus newStatus)
    {
        var shipment = _shipments.FirstOrDefault(s => s.Id == id);
        if (shipment is not null)
            shipment.Status = newStatus;
        return Task.CompletedTask;
    }
}

using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentApi(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments").RequireAuthorization();

        group.MapGet("/", async (IShipmentService service) =>
            Results.Ok(await service.GetAllShipmentsAsync()));

        group.MapGet("/track/{trackingNumber}", async (string trackingNumber, IShipmentService service) =>
        {
            var shipment = await service.GetShipmentByTrackingNumberAsync(trackingNumber);
            return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
        });

        group.MapPut("/{id:int}/status", async (int id, ShipmentStatus newStatus, IShipmentService service) =>
        {
            await service.UpdateStatusAsync(id, newStatus);
            return Results.NoContent();
        }).RequireAuthorization(policy => policy.RequireRole("Dispatcher"));
    }
}

